module move_sequences (\n    input wire [63:0] a11,\n    input wire [63:0] a12,\n    input wire [63:0] a21,\n    input wire [63:0] a22,\n    input wire [63:0] N,\n    output reg [63:0] result\n);\n\n    localparam [31:0] MOD = 32'd1000000007;\n\n    // Helper function for modular exponentiation\n    function [63:0] mod_pow;\n        input [63:0] base;\n        input [63:0] exp;\n        reg [63:0] result;\n        reg [63:0] b;\n        reg [63:0] e;\n        integer i;\n    begin\n        result = 64'd1;\n        b = base % MOD;\n        e = exp;\n        for (i = 0; i < 64; i = i + 1) begin\n            if (e == 0) begin\n                // Early exit\n            end else begin\n                if (e[0] == 1) begin\n                    result = (result * b) % MOD;\n                end\n                b = (b * b) % MOD;\n                e = e >> 1;\n            end\n        end\n        mod_pow = result;\n    end\n    endfunction\n\n    always @(*) begin\n        reg [63:0] P;\n        reg [63:0] part1;\n        reg [63:0] part2;\n        \n        // Check if all players have the same type\n        if ((a11 > 0 && a12 == 0 && a21 == 0 && a22 == 0) ||\n            (a12 > 0 && a11 == 0 && a21 == 0 && a22 == 0) ||\n            (a21 > 0 && a11 == 0 && a12 == 0 && a22 == 0) ||\n            (a22 > 0 && a11 == 0 && a12 == 0 && a21 == 0)) begin\n            // Determine P\n            if (a11 > 0) P = a11;\n            else if (a12 > 0) P = a12;\n            else if (a21 > 0) P = a21;\n            else P = a22;\n            \n            if (N == 0) begin\n                result = 64'd1;\n            end else if (P < 2) begin\n                result = 64'd0;\n            end else if (N == 1) begin\n                result = (P * (P - 64'd1)) % MOD;\n            end else begin\n                part1 = (P * (P - 64'd1)) % MOD;\n                part2 = mod_pow(P - 64'd2, N - 64'd1);\n                result = (part1 * part2) % MOD;\n            end\n        end else begin\n            // Mixed types - output 0\n            result = 64'd0;\n        end\n    end\n\nendmodule